        public void Person_FullName_WithDifferentNames_ReturnsCorrectFormat()
        {
            // Arrange
            var instructor = new Instructor
            {
                FirstMidName = "Jane",
                LastName = "Smith",
                HireDate = DateTime.Today
            };

            // Act
            var fullName = instructor.FullName;

            // Assert
            Assert.Equal("Smith, Jane", fullName);
        }

