        public void ErrorViewModel_ShowRequestId_WithRequestId_ReturnsTrue()
        {
            // Arrange
            var model = new ErrorViewModel { RequestId = "abc123" };

            // Act & Assert
            Assert.True(model.ShowRequestId);
        }

        [Fact]
        public void ErrorViewModel_ShowRequestId_WithNullRequestId_ReturnsFalse()
        {
            // Arrange
            var model = new ErrorViewModel { RequestId = null };

            // Act & Assert
            Assert.False(model.ShowRequestId);
        }

        [Fact]
        public void ErrorViewModel_ShowRequestId_WithEmptyRequestId_ReturnsFalse()
        {
            // Arrange
            var model = new ErrorViewModel { RequestId = "" };

            // Act & Assert
            Assert.False(model.ShowRequestId);
        }

        [Fact]
        public void Student_EnrollmentDate_CanBeSet()
        {
            // Arrange
            var date = new DateTime(2024, 1, 15);
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = date
            };

            // Assert
            Assert.Equal(date, student.EnrollmentDate);
        }

        [Fact]
        public void Course_Properties_CanBeSetAndRead()
        {
            // Arrange & Act
            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1
            };

            // Assert
            Assert.Equal(1050, course.CourseID);
            Assert.Equal("Chemistry", course.Title);
            Assert.Equal(3, course.Credits);
            Assert.Equal(1, course.DepartmentID);
        }

        [Fact]
        public void Department_Properties_CanBeSetAndRead()
        {
            // Arrange & Act
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 350000m,
                StartDate = new DateTime(2007, 9, 1),
                InstructorID = 5
            };

            // Assert
            Assert.Equal(1, dept.DepartmentID);
            Assert.Equal("Engineering", dept.Name);
            Assert.Equal(350000m, dept.Budget);
            Assert.Equal(new DateTime(2007, 9, 1), dept.StartDate);
            Assert.Equal(5, dept.InstructorID);
        }

        [Fact]
        public void Department_InstructorID_CanBeNull()
        {
            // Arrange & Act
            var dept = new Department { Name = "Test", InstructorID = null };

            // Assert
            Assert.Null(dept.InstructorID);
        }

        [Fact]
        public void Enrollment_Grade_CanBeNull()
        {
            // Arrange & Act
            var enrollment = new Enrollment
            {
                EnrollmentID = 1,
                CourseID = 100,
                StudentID = 1,
                Grade = null
            };

            // Assert
            Assert.Null(enrollment.Grade);
        }

        [Fact]
        public void Enrollment_Grade_CanBeSet()
        {
            // Arrange & Act
            var enrollment = new Enrollment
            {
                EnrollmentID = 1,
                CourseID = 100,
                StudentID = 1,
                Grade = Grade.A
            };

            // Assert
            Assert.Equal(Grade.A, enrollment.Grade);
        }

        [Fact]
        public void Notification_Properties_CanBeSetAndRead()
        {
            // Arrange
            var now = DateTime.Now;
            var notification = new Notification
            {
                Id = 1,
                EntityType = "Student",
                EntityId = "42",
                Operation = "CREATE",
                Message = "Test message",
                CreatedAt = now,
                CreatedBy = "Admin",
                IsRead = false,
                ReadAt = null
            };

            // Assert
            Assert.Equal(1, notification.Id);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("Test message", notification.Message);
            Assert.Equal(now, notification.CreatedAt);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
            Assert.Null(notification.ReadAt);
        }

        [Fact]
        public void CourseAssignment_Properties_CanBeSetAndRead()
        {
            // Arrange & Act
            var ca = new CourseAssignment
            {
                InstructorID = 1,
                CourseID = 1050
            };

            // Assert
            Assert.Equal(1, ca.InstructorID);
            Assert.Equal(1050, ca.CourseID);
        }

        [Fact]
        public void OfficeAssignment_Properties_CanBeSetAndRead()
        {
            // Arrange & Act
            var oa = new OfficeAssignment
            {
                InstructorID = 1,
                Location = "Smith 17"
            };

            // Assert
            Assert.Equal(1, oa.InstructorID);
            Assert.Equal("Smith 17", oa.Location);
        }

        [Fact]
        public void EntityOperation_HasExpectedValues()
        {
            // Assert
            Assert.Equal(0, (int)EntityOperation.CREATE);
            Assert.Equal(1, (int)EntityOperation.UPDATE);
            Assert.Equal(2, (int)EntityOperation.DELETE);
        }
    }
}

