using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_EmptyDatabase_SeedsStudents()
        {
            // Arrange
            var dbName = Guid.NewGuid().ToString();
            using var context = TestDbContextHelper.CreateContext(dbName);

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(8, context.Students.Count());
            Assert.Contains(context.Students, s => s.LastName == "Alexander" && s.FirstMidName == "Carson");
            Assert.Contains(context.Students, s => s.LastName == "Olivetto" && s.FirstMidName == "Nino");
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsInstructors()
        {
            // Arrange
            var dbName = Guid.NewGuid().ToString();
            using var context = TestDbContextHelper.CreateContext(dbName);

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(5, context.Instructors.Count());
            Assert.Contains(context.Instructors, i => i.LastName == "Abercrombie");
            Assert.Contains(context.Instructors, i => i.LastName == "Zheng");
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsDepartments()
        {
            // Arrange
            var dbName = Guid.NewGuid().ToString();
            using var context = TestDbContextHelper.CreateContext(dbName);

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(4, context.Departments.Count());
            Assert.Contains(context.Departments, d => d.Name == "English");
            Assert.Contains(context.Departments, d => d.Name == "Mathematics");
            Assert.Contains(context.Departments, d => d.Name == "Engineering");
            Assert.Contains(context.Departments, d => d.Name == "Economics");
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsCourses()
        {
            // Arrange
            var dbName = Guid.NewGuid().ToString();
            using var context = TestDbContextHelper.CreateContext(dbName);

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(7, context.Courses.Count());
            Assert.Contains(context.Courses, c => c.Title == "Chemistry" && c.CourseID == 1050);
            Assert.Contains(context.Courses, c => c.Title == "Literature" && c.CourseID == 2042);
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsEnrollments()
        {
            // Arrange
            var dbName = Guid.NewGuid().ToString();
            using var context = TestDbContextHelper.CreateContext(dbName);

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(11, context.Enrollments.Count());
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsOfficeAssignments()
        {
            // Arrange
            var dbName = Guid.NewGuid().ToString();
            using var context = TestDbContextHelper.CreateContext(dbName);

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(3, context.OfficeAssignments.Count());
            Assert.Contains(context.OfficeAssignments, o => o.Location == "Smith 17");
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsCourseAssignments()
        {
            // Arrange
            var dbName = Guid.NewGuid().ToString();
            using var context = TestDbContextHelper.CreateContext(dbName);

            // Act
            DbInitializer.Initialize(context);

            // Assert
            Assert.Equal(8, context.CourseAssignments.Count());
        }

        [Fact]
        public void Initialize_DatabaseAlreadySeeded_SkipsSeeding()
        {
            // Arrange
            var dbName = Guid.NewGuid().ToString();
            using var context = TestDbContextHelper.CreateContext(dbName);

            // Seed once
            DbInitializer.Initialize(context);
            var studentCount = context.Students.Count();
            var courseCount = context.Courses.Count();

            // Act - seed again
            DbInitializer.Initialize(context);

            // Assert - counts should not change
            Assert.Equal(studentCount, context.Students.Count());
            Assert.Equal(courseCount, context.Courses.Count());
        }

        [Fact]
        public void Initialize_SetsCorrectEnrollmentDates()
        {
            // Arrange
            var dbName = Guid.NewGuid().ToString();
            using var context = TestDbContextHelper.CreateContext(dbName);

            // Act
            DbInitializer.Initialize(context);

            // Assert
            var carson = context.Students.Single(s => s.LastName == "Alexander");
            Assert.Equal(DateTime.Parse("2010-09-01"), carson.EnrollmentDate);

            var nino = context.Students.Single(s => s.LastName == "Olivetto");
            Assert.Equal(DateTime.Parse("2005-09-01"), nino.EnrollmentDate);
        }

        [Fact]
        public void Initialize_SetsCorrectCourseCredits()
        {
            // Arrange
            var dbName = Guid.NewGuid().ToString();
            using var context = TestDbContextHelper.CreateContext(dbName);

            // Act
            DbInitializer.Initialize(context);

            // Assert
            var chemistry = context.Courses.Single(c => c.CourseID == 1050);
            Assert.Equal(3, chemistry.Credits);
            Assert.Equal("Chemistry", chemistry.Title);

            var calculus = context.Courses.Single(c => c.CourseID == 1045);
            Assert.Equal(4, calculus.Credits);
            Assert.Equal("Calculus", calculus.Title);
        }

        [Fact]
        public void Initialize_LinksDepartmentsToInstructors()
        {
            // Arrange
            var dbName = Guid.NewGuid().ToString();
            using var context = TestDbContextHelper.CreateContext(dbName);

            // Act
            DbInitializer.Initialize(context);

            // Assert
            var english = context.Departments.Single(d => d.Name == "English");
            var abercrombie = context.Instructors.Single(i => i.LastName == "Abercrombie");
            Assert.Equal(abercrombie.ID, english.InstructorID);
        }

        [Fact]
        public void Initialize_SetsEnrollmentGrades()
        {
            // Arrange
            var dbName = Guid.NewGuid().ToString();
            using var context = TestDbContextHelper.CreateContext(dbName);

            // Act
            DbInitializer.Initialize(context);

            // Assert - check that some enrollments have grades and some don't
            var enrollments = context.Enrollments.ToList();
            Assert.Contains(enrollments, e => e.Grade == Grade.A);
            Assert.Contains(enrollments, e => e.Grade == Grade.B);
            Assert.Contains(enrollments, e => e.Grade == null);
        }
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            _context = TestDbContextHelper.CreateContext();
            _controller = new StudentsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private void SeedStudents()
        {
            _context.Students.AddRange(
                new Student { FirstMidName = "Carson", LastName = "Alexander", EnrollmentDate = DateTime.Parse("2010-09-01") },
                new Student { FirstMidName = "Meredith", LastName = "Alonso", EnrollmentDate = DateTime.Parse("2012-09-01") },
                new Student { FirstMidName = "Arturo", LastName = "Anand", EnrollmentDate = DateTime.Parse("2013-09-01") },
                new Student { FirstMidName = "Gytis", LastName = "Barzdukas", EnrollmentDate = DateTime.Parse("2012-09-01") },
                new Student { FirstMidName = "Yan", LastName = "Li", EnrollmentDate = DateTime.Parse("2012-09-01") }
            );
            _context.SaveChanges();
        }

        // --- Index tests ---

        [Fact]
        public void Index_NoParams_ReturnsViewWithStudentsOrderedByLastName()
        {
            // Arrange
            SeedStudents();

            // Act
            var result = _controller.Index(null, null, null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.True(model.Count > 0);
            // Default sort is by LastName ascending
            Assert.Equal("Alexander", model.First().LastName);
        }

        [Fact]
        public void Index_NameDescSort_ReturnsStudentsOrderedByLastNameDescending()
