        [Theory]
        [InlineData(".jpg")]
        [InlineData(".jpeg")]
        [InlineData(".png")]
        [InlineData(".gif")]
        [InlineData(".bmp")]
        public void CreatePost_AllowedFileExtensions_DoesNotRejectExtension(string extension)
        {
            // Arrange
            SeedDepartmentAndCourse();
            var dept = _context.Departments.First();
            var course = new Course
            {
                CourseID = 2000 + extension.GetHashCode(), // unique ID per extension
                Title = "Test",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns($"test{extension}");
            mockFile.Setup(f => f.Length).Returns(1024);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>())); // no-op

            // Act
            var result = _controller.Create(course, mockFile.Object);

            // Assert - should redirect (not return view with error) since extension is allowed
            // File write may fail due to temp path but extension validation should pass
            if (result is ViewResult viewResult)
            {
                // If it fails, it should NOT be because of extension
                Assert.False(_controller.ModelState.ContainsKey("teachingMaterialImage") &&
                    _controller.ModelState["teachingMaterialImage"]!.Errors.Any(e => e.ErrorMessage.Contains("valid image file")),
                    $"Extension {extension} should be allowed but was rejected");
            }
        }

