        [Fact]
        public void CreatePost_InvalidFileExtension_ReturnsViewWithError()
        {
            // Arrange
            SeedDepartmentAndCourse();
            var dept = _context.Departments.First();
            var course = new Course
            {
                CourseID = 2000,
                Title = "Test",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.exe");
            mockFile.Setup(f => f.Length).Returns(1024);

            // Act
            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            Assert.Contains("valid image file", _controller.ModelState["teachingMaterialImage"]!.Errors.First().ErrorMessage);
        }

        [Theory]
        [InlineData(".pdf")]
        [InlineData(".doc")]
        [InlineData(".txt")]
        [InlineData(".exe")]
        public void CreatePost_DisallowedFileExtensions_ReturnsError(string extension)
        {
            // Arrange
            SeedDepartmentAndCourse();
            var dept = _context.Departments.First();
            var course = new Course
            {
                CourseID = 2000,
                Title = "Test",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns($"test{extension}");
            mockFile.Setup(f => f.Length).Returns(1024);

            // Act
            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void CreatePost_FileOver5MB_ReturnsViewWithError()
        {
            // Arrange
            SeedDepartmentAndCourse();
            var dept = _context.Departments.First();
            var course = new Course
            {
                CourseID = 2000,
                Title = "Test",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.jpg");
            mockFile.Setup(f => f.Length).Returns(6 * 1024 * 1024); // 6MB

            // Act
            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            Assert.Contains("5MB", _controller.ModelState["teachingMaterialImage"]!.Errors.First().ErrorMessage);
        }

        [Theory]
        [InlineData(".jpg")]
        [InlineData(".jpeg")]
        [InlineData(".png")]
        [InlineData(".gif")]
        [InlineData(".bmp")]
        public void CreatePost_AllowedFileExtensions_DoesNotRejectExtension(string extension)
        {
            // Arrange
            SeedDepartmentAndCourse();
            var dept = _context.Departments.First();
            var course = new Course
            {
                CourseID = 2000 + extension.GetHashCode(), // unique ID per extension
                Title = "Test",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns($"test{extension}");
            mockFile.Setup(f => f.Length).Returns(1024);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>())); // no-op

            // Act
            var result = _controller.Create(course, mockFile.Object);

