using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;
        private readonly NotificationService _notificationService;

        public NotificationsControllerTests()
        {
            _context = TestDbContextHelper.CreateContext();
            _controller = new NotificationsController(_context);
            _notificationService = new NotificationService();
            // Drain the static queue
            while (_notificationService.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain the static queue
            while (_notificationService.ReceiveNotification() != null) { }
            _controller.Dispose();
            _context.Dispose();
            _notificationService.Dispose();
        }

        [Fact]
        public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
        {
            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.NotNull(result);
            var jsonValue = result.Value;
            Assert.NotNull(jsonValue);

            // Use reflection to check anonymous type properties
            var type = jsonValue.GetType();
            var successProp = type.GetProperty("success");
            var countProp = type.GetProperty("count");
            Assert.NotNull(successProp);
            Assert.NotNull(countProp);
            Assert.True((bool)successProp.GetValue(jsonValue)!);
            Assert.Equal(0, (int)countProp.GetValue(jsonValue)!);
        }

        [Fact]
        public void GetNotifications_WithItems_ReturnsNotifications()
        {
            // Arrange - add notifications via the static queue
            _notificationService.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE);
            _notificationService.SendNotification("Course", "2", "Math", EntityOperation.UPDATE);

            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.NotNull(result);
            var jsonValue = result.Value;
            Assert.NotNull(jsonValue);

            var type = jsonValue.GetType();
            var successProp = type.GetProperty("success");
            var countProp = type.GetProperty("count");
            var notificationsProp = type.GetProperty("notifications");
            Assert.True((bool)successProp!.GetValue(jsonValue)!);
            Assert.Equal(2, (int)countProp!.GetValue(jsonValue)!);

            var notifications = (List<Notification>)notificationsProp!.GetValue(jsonValue)!;
            Assert.Equal(2, notifications.Count);
            Assert.Equal("Student", notifications[0].EntityType);
            Assert.Equal("Course", notifications[1].EntityType);
        }

        [Fact]
        public void GetNotifications_MoreThan10Items_LimitsTo10()
        {
            // Arrange
            for (int i = 0; i < 15; i++)
            {
                _notificationService.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
            }

            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.NotNull(result);
            var jsonValue = result.Value;
            Assert.NotNull(jsonValue);

            var type = jsonValue.GetType();
            var countProp = type.GetProperty("count");
            Assert.Equal(10, (int)countProp!.GetValue(jsonValue)!);
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccess()
        {
            // Act
            var result = _controller.MarkAsRead(1);

            // Assert
            Assert.NotNull(result);
            var jsonValue = result.Value;
            Assert.NotNull(jsonValue);

            var type = jsonValue.GetType();
            var successProp = type.GetProperty("success");
            Assert.True((bool)successProp!.GetValue(jsonValue)!);
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            // Act
            var result = _controller.Index();

            // Assert
            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void GetNotifications_ConsumesFromQueue_SecondCallReturnsLess()
        {
            // Arrange
            _notificationService.SendNotification("Student", "1", EntityOperation.CREATE);
            _notificationService.SendNotification("Course", "2", EntityOperation.UPDATE);

            // Act - first call consumes
            _controller.GetNotifications();
            var result = _controller.GetNotifications();

            // Assert - second call gets nothing since queue was drained
            var jsonValue = result.Value;
            Assert.NotNull(jsonValue);
            var type = jsonValue.GetType();
            var countProp = type.GetProperty("count");
            Assert.Equal(0, (int)countProp!.GetValue(jsonValue)!);
        }
    }
}

