[Fact]
public void CreatePost_FileOver5MB_ReturnsViewWithError()
{
    // Arrange
    SeedDepartmentAndCourse();
    var dept = _context.Departments.First();
    var course = new Course
    {
        CourseID = 2000,
        Title = "Test",
        Credits = 3,
        DepartmentID = dept.DepartmentID
    };

    var mockFile = new Mock<IFormFile>();
    mockFile.Setup(f => f.FileName).Returns("test.jpg");
    mockFile.Setup(f => f.Length).Returns(6 * 1024 * 1024); // 6MB

    // Act
    var result = _controller.Create(course, mockFile.Object) as ViewResult;

    // Assert
    Assert.NotNull(result);
    Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    Assert.Contains("5MB", _controller.ModelState["teachingMaterialImage"]!.Errors.First().ErrorMessage);
}

[Fact]
public void CreatePost_FileExactly5MB_IsAllowed()
{
    // Arrange - exactly 5MB should be allowed (check is > 5MB, not >=)
    SeedDepartmentAndCourse();
    var dept = _context.Departments.First();
    var course = new Course
    {
        CourseID = 3000,
        Title = "Boundary",
        Credits = 3,
        DepartmentID = dept.DepartmentID
    };

    var mockFile = new Mock<IFormFile>();
    mockFile.Setup(f => f.FileName).Returns("test.jpg");
    mockFile.Setup(f => f.Length).Returns(5 * 1024 * 1024); // exactly 5MB
    mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));

    // Act
    var result = _controller.Create(course, mockFile.Object);

    // Assert - should NOT be rejected for size
    if (result is ViewResult viewResult)
    {
        Assert.False(
            _controller.ModelState.ContainsKey("teachingMaterialImage") &&
            _controller.ModelState["teachingMaterialImage"]!.Errors.Any(e => e.ErrorMessage.Contains("5MB")),
            "File exactly 5MB should not be rejected for size");
    }
}

[Fact]
public void CreatePost_UppercaseFileExtension_IsAccepted()
{
    // Arrange - .JPG should be accepted (case-insensitive)
    SeedDepartmentAndCourse();
    var dept = _context.Departments.First();
    var course = new Course
    {
        CourseID = 4000,
        Title = "CaseTest",
        Credits = 3,
        DepartmentID = dept.DepartmentID
    };

    var mockFile = new Mock<IFormFile>();
    mockFile.Setup(f => f.FileName).Returns("TEST.JPG");
    mockFile.Setup(f => f.Length).Returns(1024);
    mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));

    // Act
    var result = _controller.Create(course, mockFile.Object);

    // Assert - uppercase extension should NOT be rejected
    if (result is ViewResult viewResult)
    {
        Assert.False(
            _controller.ModelState.ContainsKey("teachingMaterialImage") &&
            _controller.ModelState["teachingMaterialImage"]!.Errors.Any(e => e.ErrorMessage.Contains("valid image file")),
            "Uppercase .JPG extension should be accepted");
    }
}

